<script setup lang="ts">
import {computed,onMounted,ref,watch,nextTick} from 'vue';import {useRoute} from 'vue-router';import {clone,getStudio,roleLabels,saveStudio,type StudioPayload,type StudioRoute} from './content-studio-api';
import StudioOpeningDisplay from './StudioOpeningDisplay.vue';
import {useEditorSafety} from './editor-safety';import StudioEditorSafety from './StudioEditorSafety.vue';
const previewLocale=ref<'zh'|'en'>('zh');
import StudioPlaceCreate from './StudioPlaceCreate.vue';import type {PlaceCreationContext} from '../../shared/studio-place-creation';
const creating=ref<PlaceCreationContext|null>(null),addQuery=ref('');
const routeInfo=useRoute(),payload=ref<StudioPayload|null>(null),route=ref<StudioRoute|null>(null),message=ref(''),busy=ref(false),showAdd=ref<string|null>(null),dragged=ref<string|null>(null),preview=ref(false);
async function load(){payload.value=await getStudio();route.value=clone(payload.value.document.routes.find(r=>r.id===routeInfo.params.id)!);safety.capture();await nextTick();const target=routeInfo.query.group?'group-'+routeInfo.query.group:routeInfo.query.stage?'stage-'+routeInfo.query.stage:'';if(target)document.getElementById(target)?.scrollIntoView({block:'center'});}onMounted(load);
const safety=useEditorSafety({payload,current:()=>route.value,setCurrent:v=>route.value=v,select:doc=>doc.routes.find(r=>r.id===route.value!.id),save,busy:()=>busy.value});watch(()=>routeInfo.params.id,()=>void load());
const place=(id:string)=>payload.value?.document.places[id];const members=(stageId:string,groupId:string|null)=>route.value?.memberships.filter(m=>m.stageId===stageId&&m.groupId===groupId&&m.visible).sort((a,b)=>a.order-b.order)||[];
const unassigned=computed(()=>{const used=new Set(route.value?.memberships.filter(m=>m.visible).map(m=>m.placeId));return Object.values(payload.value?.document.places||{}).filter(p=>!p.archivedAt&&!used.has(p.id)&&[p.name.zh,p.name.en,p.id].join(' ').toLowerCase().includes(addQuery.value.toLowerCase()));});
function normalize(stageId:string,groupId:string|null){members(stageId,groupId).forEach((m,i)=>m.order=(i+1)*10);}
function move(placeId:string,direction:-1|1){const member=route.value!.memberships.find(m=>m.placeId===placeId)!;const list=members(member.stageId,member.groupId),index=list.findIndex(m=>m.placeId===placeId),other=list[index+direction];if(!other)return;[member.order,other.order]=[other.order,member.order];}
function moveTo(member:any,value:string){const [stageId,group]=value.split('|');member.stageId=stageId;member.groupId=group||null;member.order=members(stageId,member.groupId).length*10+10;}
function addPlace(stageId:string,placeId:string,groupId:string|null=null){if(route.value!.memberships.some(m=>m.placeId===placeId&&m.visible))return;route.value!.memberships=route.value!.memberships.filter(m=>m.placeId!==placeId);route.value!.memberships.push({placeId,stageId,groupId,role:'secondary-stop',order:members(stageId,groupId).length*10+10,visible:true});showAdd.value=null;}
function addGroup(stage:any){stage.groups.push({id:`group-${crypto.randomUUID()}`,title:{zh:'新分组',en:''},summary:{zh:'',en:''},order:(stage.groups.length+1)*10,published:false,visible:true,archivedAt:null});}
function addStage(){route.value!.stages.push({id:`stage-${crypto.randomUUID()}`,title:{zh:'新阶段',en:''},summary:{zh:'',en:''},order:(route.value!.stages.length+1)*10,published:false,visible:true,archivedAt:null,groups:[]});}
function archiveStage(stage:any){if(!confirm(`归档阶段“${stage.title.zh}”？阶段内地点关系会保留但不再公开。`))return;stage.archivedAt=new Date().toISOString();stage.visible=false;route.value!.memberships.filter(m=>m.stageId===stage.id).forEach(m=>m.visible=false);}
function archiveGroup(stage:any,group:any){if(!confirm(`归档“${group.title.zh}”？其中地点会移回本阶段其他地点。`))return;route.value!.memberships.filter(m=>m.groupId===group.id).forEach(m=>m.groupId=null);group.archivedAt=new Date().toISOString();group.visible=false;}
function drop(stageId:string,groupId:string|null){if(!dragged.value)return;const member=route.value!.memberships.find(m=>m.placeId===dragged.value);if(member){member.stageId=stageId;member.groupId=groupId;member.order=members(stageId,groupId).length*10+10;}dragged.value=null;}
async function save(){if(!payload.value||!route.value||busy.value)return false;busy.value=true;try{const doc=clone(payload.value.document),index=doc.routes.findIndex(r=>r.id===route.value!.id);doc.routes[index]=clone(route.value);const r=await saveStudio(payload.value,doc,'route',route.value.id,`修改路线：${route.value.name.zh}`);message.value=`草稿已保存（版本 ${r.draftRevision}），公开网站尚未改变。`;payload.value.document=doc;payload.value.draftRevision=r.draftRevision;safety.capture(doc.routes[index]);return true;}catch(e){safety.fail(e);message.value='';return false;}finally{busy.value=false;}}
function startCreate(stageId:string,groupId:string|null){creating.value={routeId:route.value!.id,stageId,groupId,role:'secondary-stop',order:members(stageId,groupId).length*10+10};}
function created(result:{id:string;draftRevision:number;document:import('../../shared/content-studio').ContentStudioDocument}){payload.value!.document=result.document;payload.value!.draftRevision=result.draftRevision;route.value=clone(result.document.routes.find(r=>r.id===route.value!.id)!);creating.value=null;safety.capture();message.value='新地点草稿已保存，当前路线修改和地点关联已一起保存。';}
</script>
<template><div v-if="payload&&route" class="workspace-page studio-page route-studio"><div class="workspace-title"><div><RouterLink to="/studio/routes">← 返回路线</RouterLink><p class="kicker">路线可视化编辑</p><input v-model="route.name.zh" class="inline-title"><textarea v-model="route.summary.zh" class="route-summary-input" aria-label="路线简介" rows="4"></textarea><div class="theme-checks"><label><input v-model="route.published" type="checkbox">公开</label><label><input v-model="route.featured" type="checkbox">Explore 推荐</label><label>顺序<input v-model.number="route.order" type="number"></label></div></div><div class="workspace-actions"><button class="button quiet" @click="preview=!preview">{{preview?'继续编辑':'预览本地草稿'}}</button><button class="primary-action" :disabled="busy" @click="save">保存草稿</button></div></div><StudioPlaceCreate v-if="creating" :payload="payload" :route-draft="route" :context="creating" @cancel="creating=null" @created="created"/><StudioEditorSafety :state="safety"/><p v-if="message" class="inline-message">{{message}}</p>
<section v-if="preview" class="route-draft-preview"><label>预览语言<select v-model="previewLocale"><option value="zh">中文</option><option value="en">English</option></select></label><p>本地预览 · 当前草稿，包含尚未公开的阶段与分组；不改变公开网站。</p><article v-for="s in route.stages.filter(x=>!x.archivedAt).sort((a,b)=>a.order-b.order)" :key="s.id"><h2>{{s.title.zh}}</h2><section v-for="g in s.groups.filter(x=>!x.archivedAt).sort((a,b)=>a.order-b.order)" :key="g.id"><h3>{{g.title.zh}}</h3><p v-if="g.summary.zh">{{g.summary.zh}}</p><div v-for="m in members(s.id,g.id)" :key="m.placeId" class="route-place-row"><strong>{{place(m.placeId)?.name.zh}}</strong><small>{{roleLabels[m.role]}}</small><StudioOpeningDisplay v-if="place(m.placeId)" :place="place(m.placeId)!" :locale="previewLocale"/></div></section><div v-for="m in members(s.id,null)" :key="m.placeId" class="route-place-row"><strong>{{place(m.placeId)?.name.zh}}</strong><small>{{roleLabels[m.role]}}</small><StudioOpeningDisplay v-if="place(m.placeId)" :place="place(m.placeId)!" :locale="previewLocale"/></div></article></section><section v-for="(stage,si) in route.stages.filter(s=>!s.archivedAt).sort((a,b)=>a.order-b.order)" :key="stage.id" v-show="!preview" class="route-stage-card" :id="'stage-'+stage.id"><header><span>{{String(si+1).padStart(2,'0')}}</span><input v-model="stage.title.zh"><button class="quiet" @click="addGroup(stage)">＋ 添加分组</button><button class="remove-button" @click="archiveStage(stage)">归档阶段</button></header>
<div v-for="group in stage.groups.filter(g=>!g.archivedAt).sort((a,b)=>a.order-b.order)" :key="group.id" :class="['route-group',{'route-location-target':routeInfo.query.group===group.id}]" :id="'group-'+group.id" @dragover.prevent @drop="drop(stage.id,group.id)"><div class="route-group-heading"><input v-model="group.title.zh"><button class="remove-button" @click="archiveGroup(stage,group)">归档</button></div><div class="route-group-section"><h4>值得停留</h4><article v-for="member in members(stage.id,group.id).filter(m=>!['service','junction'].includes(m.role))" :key="member.placeId" draggable="true" @dragstart="dragged=member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button><select :value="`${member.stageId}|${member.groupId||''}`" @change="moveTo(member,($event.target as HTMLSelectElement).value)"><optgroup v-for="s in route.stages.filter(x=>!x.archivedAt)" :label="s.title.zh"><option :value="`${s.id}|`">{{s.title.zh}} · 未分组</option><option v-for="g in s.groups.filter(x=>!x.archivedAt)" :value="`${s.id}|${g.id}`">{{g.title.zh}}</option></optgroup></select></article><h4>服务与路口</h4><article v-for="member in members(stage.id,group.id).filter(m=>['service','junction'].includes(m.role))" :key="member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button><select :value="`${member.stageId}|${member.groupId||''}`" @change="moveTo(member,($event.target as HTMLSelectElement).value)"><optgroup v-for="s in route.stages.filter(x=>!x.archivedAt)" :label="s.title.zh"><option :value="`${s.id}|`">{{s.title.zh}} · 未分组</option><option v-for="g in s.groups.filter(x=>!x.archivedAt)" :value="`${s.id}|${g.id}`">{{g.title.zh}}</option></optgroup></select></article></div><div class="creation-entry-actions"><button class="quiet" @click="showAdd=showAdd===stage.id+'|'+(group.id||'')?null:stage.id+'|'+(group.id||'');addQuery=''">＋ 添加已有地点</button><button class="primary-action" @click="startCreate(stage.id,group.id)">＋ 新建地点</button></div><div v-if="showAdd===stage.id+'|'+(group.id||'')" class="available-content"><input v-model="addQuery" placeholder="搜索已有地点名称或编号"><button v-for="p in unassigned" :key="p.id" @click="addPlace(stage.id,p.id,group.id)">{{p.name.zh}} · {{p.id}}</button><p v-if="!unassigned.length">{{addQuery?'没有匹配的已有地点。':'当前没有其他可添加的已有地点，你可以新建地点。'}}</p><button @click="startCreate(stage.id,group.id)">＋ 新建地点</button></div></div>
<div class="route-group fallback" @dragover.prevent @drop="drop(stage.id,null)"><h3>{{stage.groups.some(g=>!g.archivedAt)?'本阶段其他地点':'阶段地点'}}</h3><article v-for="member in members(stage.id,null)" :key="member.placeId" draggable="true" @dragstart="dragged=member.placeId" class="route-place-row"><span>☰</span><RouterLink :to="`/studio/places/${member.placeId}`"><strong>{{place(member.placeId)?.name.zh}}</strong><small>{{member.placeId}}</small></RouterLink><select v-model="member.role"><option v-for="(label,key) in roleLabels" :value="key">{{label}}</option></select><button @click="move(member.placeId,-1)">↑</button><button @click="move(member.placeId,1)">↓</button><select :value="`${member.stageId}|`" @change="moveTo(member,($event.target as HTMLSelectElement).value)"><optgroup v-for="s in route.stages.filter(x=>!x.archivedAt)" :label="s.title.zh"><option :value="`${s.id}|`">{{s.title.zh}} · 未分组</option><option v-for="g in s.groups.filter(x=>!x.archivedAt)" :value="`${s.id}|${g.id}`">{{g.title.zh}}</option></optgroup></select></article><div class="creation-entry-actions"><button class="quiet" @click="showAdd=showAdd===stage.id+'|'+''?null:stage.id+'|'+'';addQuery=''">＋ 添加已有地点</button><button class="primary-action" @click="startCreate(stage.id,null)">＋ 新建地点</button></div><div v-if="showAdd===stage.id+'|'+''" class="available-content"><input v-model="addQuery" placeholder="搜索已有地点名称或编号"><button v-for="p in unassigned" :key="p.id" @click="addPlace(stage.id,p.id,null)">{{p.name.zh}} · {{p.id}}</button><p v-if="!unassigned.length">{{addQuery?'没有匹配的已有地点。':'当前没有其他可添加的已有地点，你可以新建地点。'}}</p><button @click="startCreate(stage.id,null)">＋ 新建地点</button></div></div></section><button v-if="!preview" class="button quiet" @click="addStage">＋ 新增阶段</button><div class="editor-action-bar"><button class="primary-action" :disabled="busy" @click="save">保存路线草稿</button></div></div></template>
